INSERT INTO `sys_oper_log` VALUES (253, '新增内容', 0, 'Archives/add', 'POST', 1, 'admin', '', '/yscms/archives/add', '127.0.0.1', '', '{\"model_id\":\"1\",\"channel_id\":\"5\",\"title\":\"挑选长久安心的出行伙伴 入手豪华燃油车正当时\",\"image\":\"\\/storage\\/2026\\/09\\/14\\/132042_83f6af78.png\",\"keywords\":\"\",\"description\":\"挑选长久安心的出行伙伴 入手豪华燃油车正当时\",\"tags\":\"\",\"content\":\"<p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 2em;\\\">购车，从来都不是简单的选择代步工具，而是挑选长久安心的出行伙伴。梅赛德斯-奔驰将以深厚的车型积淀与市场口碑契合当下消费者对“省心豪华燃油车”的核心诉求。<\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-align: center;\\\"><img src=\\\"https:\\/\\/www.cqn.com.cn\\/auto\\/img\\/2026-08\\/18\\/9169131_b313dab2-9688-437a-8cb0-677d68dbc435.jpg\\\" style=\\\"text-size-adjust: none; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); width: 788.5px; height: auto; margin-bottom: 0.5rem;\\\"><\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 2em;\\\"><strong style=\\\"text-size-adjust: none;\\\">核心技术铸就百年品牌 硬核实力打造难以复刻的稳定可靠<\\/strong><\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 2em;\\\">汽车的核心价值，终究归于品质与可靠。百年品牌的底气，来自世代传承的造车工艺、持续迭代的核心技术与严苛到极致的品控体系。深耕汽车领域140年的梅赛德斯-奔驰，始终坚守“安全为先、品质为本”的造车理念，依托全球统一的研发、生产、测试标准，打造每一台量产车型。<\\/p>\",\"author\":\"\",\"outlink\":\"\",\"order_num\":\"0\",\"publish_time\":\"\",\"status\":\"0\"}', '{\"code\":0,\"msg\":\"操作成功\"}', 0, '', '2026-09-14 13:21:17', 50);
INSERT INTO `sys_oper_log` VALUES (254, '上传文件', 0, 'File/upload', 'POST', 1, 'admin', '', '/ysfile/file/upload', '127.0.0.1', '', '[]', '{\"code\":0,\"msg\":\"上传成功\",\"data\":{\"id\":7,\"name\":\"QQ20260914-132240.png\",\"path\":\"2026\\/09\\/14\\/132258_be4d7ee6.png\",\"url\":\"\\/storage\\/2026\\/09\\/14\\/132258_be4d7ee6.png\",\"size\":531675,\"type\":\"image\\/png\"}}', 0, '', '2026-09-14 13:22:58', 53);
INSERT INTO `sys_oper_log` VALUES (255, '新增内容', 0, 'Archives/add', 'POST', 1, 'admin', '', '/yscms/archives/add', '127.0.0.1', '', '{\"model_id\":\"1\",\"channel_id\":\"5\",\"title\":\"小米YU7上市：定位豪华高性能SUV 25.35万元起\",\"image\":\"\\/storage\\/2026\\/09\\/14\\/132258_be4d7ee6.png\",\"keywords\":\"\",\"description\":\"小米YU7上市：定位豪华高性能SUV 25.35万元起\",\"tags\":\"\",\"content\":\"<p><span style=\\\"color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 32px;\\\">6月26日，小米汽车旗下首款SUV——小米YU7上市，定位豪华高性能SUV，推出3个版本，分别为YU7标准版、YU7 Pro版、YU7 Max版，售价25.35万元-32.99万元<\\/span><\\/p>\",\"author\":\"\",\"outlink\":\"\",\"order_num\":\"0\",\"publish_time\":\"\",\"status\":\"0\"}', '{\"code\":0,\"msg\":\"操作成功\"}', 0, '', '2026-09-14 13:23:13', 46);
