INSERT INTO `sys_oper_log` VALUES (259, '新增内容', 0, 'Archives/add', 'POST', 1, 'admin', '', '/yscms/archives/add', '127.0.0.1', '', '{\"model_id\":\"1\",\"channel_id\":\"3\",\"title\":\"主题海报｜2026年国家网络安全宣传周主题海报正式发布\",\"image\":\"\\/storage\\/2026\\/09\\/14\\/132533_55e3bb75.png\",\"keywords\":\"\",\"description\":\"主题海报｜2026年国家网络安全宣传周主题海报正式发布\",\"tags\":\"\",\"content\":\"<h1 style=\\\"padding: 0px; margin: 0px; color: rgb(0, 0, 0); font-family: -apple-system-font, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, sans-serif;\\\">主题海报｜2026年国家网络安全宣传周主题海报正式发布<\\/h1>\",\"author\":\"\",\"outlink\":\"\",\"order_num\":\"0\",\"publish_time\":\"\",\"status\":\"0\"}', '{\"code\":0,\"msg\":\"操作成功\"}', 0, '', '2026-09-14 13:25:42', 63);
