INSERT INTO `sys_oper_log` VALUES (261, '新增内容', 0, 'Archives/add', 'POST', 1, 'admin', '', '/yscms/archives/add', '127.0.0.1', '', '{\"model_id\":\"1\",\"channel_id\":\"4\",\"title\":\"新款燃油版吉利博越L图片发布 搭载千里浩瀚H5辅助驾驶系统\",\"image\":\"\\/storage\\/2026\\/09\\/14\\/132717_b15ab0da.png\",\"keywords\":\"\",\"description\":\"新款燃油版吉利博越L图片发布 搭载千里浩瀚H5辅助驾驶系统\",\"tags\":\"\",\"content\":\"<h1 style=\\\"text-size-adjust: none; margin: 50px 50px 10px; padding: 0px; font-size: 24px; font-weight: bold; text-align: center; line-height: 35px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana;\\\"><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400; text-indent: 2em; text-align: left;\\\">月9日，吉利汽车发布全新第四代博越L燃油版车型图片。新车定位为紧凑型SUV，搭载千里浩瀚H5辅助驾驶系统，并换装吉利全新一代1.5TD Pro高功发动机。<\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400;\\\"><img src=\\\"https:\\/\\/www.cqn.com.cn\\/auto\\/img\\/2026-09\\/10\\/9172101_6d7e3387-2700-4884-aa70-d970b154568b.jpg\\\" style=\\\"text-size-adjust: none; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); width: 788.5px; height: auto; margin-bottom: 0.5rem; max-width: 95%; font-family: 宋体, SimSun, 微软雅黑, &quot;Microsoft YaHei&quot;;\\\"><\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400; text-indent: 2em; text-align: left;\\\">外观延续现款车型的设计，大尺寸盾型格栅内部辅以直瀑式辐条进行点缀，车顶采用悬浮式设计，车顶前端配备激光雷达，双色车身与大尺寸多辐轮毂，提升运动感。<\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400; text-indent: 2em; text-align: left;\\\">作为核心升级，新款燃油版车型搭载千里浩瀚H5辅助驾驶系统，硬件包含激光雷达、毫米波雷达和超声波雷达在内的27颗感知传感器。系统支持城市NOA、高速NOA、HPA跨层记忆泊车功能。<\\/p><\\/h1>\",\"author\":\"\",\"outlink\":\"\",\"order_num\":\"0\",\"publish_time\":\"\",\"status\":\"0\"}', '{\"code\":0,\"msg\":\"操作成功\"}', 0, '', '2026-09-14 13:27:22', 61);
