INSERT INTO `sys_oper_log` VALUES (389, '修改内容', 0, 'Archives/edit', 'POST', 1, 'admin', '', '/yscms/archives/edit', '127.0.0.1', '', '{\"id\":10,\"channelId\":4,\"modelId\":1,\"userId\":0,\"title\":\"新款燃油版吉利博越L图片发布 搭载千里浩瀚H5辅助驾驶系统\",\"style\":\"\",\"image\":\"http:\\/\\/127.0.0.1:8088\\/storage\\/2026\\/09\\/13\\/164259_0dac420c.png\",\"images\":\"\",\"keywords\":\"\",\"description\":\"新款燃油版吉利博越L图片发布 搭载千里浩瀚H5辅助驾驶系统\",\"tags\":\"\",\"content\":\"<h1 style=\\\"text-size-adjust: none; margin: 50px 50px 10px; padding: 0px; font-size: 24px; font-weight: bold; text-align: center; line-height: 35px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana;\\\"><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400; text-indent: 2em; text-align: left;\\\">月9日，吉利汽车发布全新第四代博越L燃油版车型图片。新车定位为紧凑型SUV，搭载千里浩瀚H5辅助驾驶系统，并换装吉利全新一代1.5TD Pro高功发动机。<\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400;\\\"><img src=\\\"https:\\/\\/www.cqn.com.cn\\/auto\\/img\\/2026-09\\/10\\/9172101_6d7e3387-2700-4884-aa70-d970b154568b.jpg\\\" style=\\\"text-size-adjust: none; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); width: 788.5px; height: auto; margin-bottom: 0.5rem; max-width: 95%; font-family: 宋体, SimSun, 微软雅黑, &quot;Microsoft YaHei&quot;;\\\"><\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400; text-indent: 2em; text-align: left;\\\">外观延续现款车型的设计，大尺寸盾型格栅内部辅以直瀑式辐条进行点缀，车顶采用悬浮式设计，车顶前端配备激光雷达，双色车身与大尺寸多辐轮毂，提升运动感。<\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; font-size: 16px; font-weight: 400; text-indent: 2em; text-align: left;\\\">作为核心升级，新款燃油版车型搭载千里浩瀚H5辅助驾驶系统，硬件包含激光雷达、毫米波雷达和超声波雷达在内的27颗感知传感器。系统支持城市NOA、高速NOA、HPA跨层记忆泊车功能。<\\/p><\\/h1>\",\"outlink\":\"\",\"seotitle\":\"\",\"diyname\":\"\",\"orderNum\":0,\"views\":0,\"comments\":0,\"likes\":0,\"publishTime\":\"2026-09-14 13:27:22\",\"flag\":\"\",\"status\":\"0\",\"isguest\":\"1\",\"iscomment\":\"1\",\"createBy\":\"admin\",\"channelIds\":\"\",\"specialIds\":\"\",\"adminId\":1,\"price\":\"0.00\",\"dislikes\":0,\"memo\":\"\",\"createTime\":\"2026-09-14 13:27:22\",\"updateBy\":\"\",\"updateTime\":null,\"delFlag\":\"0\",\"author\":\"\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-22 11:05:42', 30);
INSERT INTO `sys_oper_log` VALUES (390, '修改内容', 0, 'Archives/edit', 'POST', 1, 'admin', '', '/yscms/archives/edit', '127.0.0.1', '', '{\"id\":9,\"channelId\":3,\"modelId\":1,\"userId\":0,\"title\":\"主题海报｜2026年国家网络安全宣传周主题海报正式发布\",\"style\":\"\",\"image\":\"http:\\/\\/127.0.0.1:8088\\/storage\\/2026\\/09\\/17\\/093050_8d532198.png\",\"images\":\"\",\"keywords\":\"\",\"description\":\"主题海报｜2026年国家网络安全宣传周主题海报正式发布\",\"tags\":\"\",\"content\":\"<h1 style=\\\"padding: 0px; margin: 0px; color: rgb(0, 0, 0); font-family: -apple-system-font, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, sans-serif;\\\">主题海报｜2026年国家网络安全宣传周主题海报正式发布<\\/h1>\",\"outlink\":\"\",\"seotitle\":\"\",\"diyname\":\"\",\"orderNum\":0,\"views\":11,\"comments\":1,\"likes\":0,\"publishTime\":\"2026-09-14 13:25:42\",\"flag\":\"\",\"status\":\"0\",\"isguest\":\"1\",\"iscomment\":\"1\",\"createBy\":\"admin\",\"channelIds\":\"\",\"specialIds\":\"\",\"adminId\":1,\"price\":\"0.00\",\"dislikes\":0,\"memo\":\"\",\"createTime\":\"2026-09-14 13:25:42\",\"updateBy\":\"\",\"updateTime\":null,\"delFlag\":\"0\",\"author\":\"\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-22 11:05:55', 31);
INSERT INTO `sys_oper_log` VALUES (391, '修改内容', 0, 'Archives/edit', 'POST', 1, 'admin', '', '/yscms/archives/edit', '127.0.0.1', '', '{\"id\":8,\"channelId\":3,\"modelId\":1,\"userId\":0,\"title\":\"匠心守护 技以载道——探秘奔驰售后服务体系的技术密码\",\"style\":\"\",\"image\":\"http:\\/\\/127.0.0.1:8088\\/storage\\/2026\\/09\\/17\\/091255_29dfaa0f.png\",\"images\":\"\",\"keywords\":\"\",\"description\":\"匠心守护 技以载道——探秘奔驰售后服务体系的技术密码\",\"tags\":\"\",\"content\":\"<h1 style=\\\"text-size-adjust: none; margin: 50px 50px 10px; padding: 0px; font-size: 24px; font-weight: bold; text-align: center; line-height: 35px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana;\\\">匠心守护 技以载道——探秘奔驰售后服务体系的技术密码<\\/h1>\",\"outlink\":\"\",\"seotitle\":\"\",\"diyname\":\"\",\"orderNum\":0,\"views\":2,\"comments\":0,\"likes\":0,\"publishTime\":\"2026-09-14 13:24:38\",\"flag\":\"\",\"status\":\"0\",\"isguest\":\"1\",\"iscomment\":\"1\",\"createBy\":\"admin\",\"channelIds\":\"\",\"specialIds\":\"\",\"adminId\":1,\"price\":\"0.00\",\"dislikes\":0,\"memo\":\"\",\"createTime\":\"2026-09-14 13:24:38\",\"updateBy\":\"\",\"updateTime\":null,\"delFlag\":\"0\",\"author\":\"\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-22 11:06:13', 45);
INSERT INTO `sys_oper_log` VALUES (392, '修改内容', 0, 'Archives/edit', 'POST', 1, 'admin', '', '/yscms/archives/edit', '127.0.0.1', '', '{\"id\":7,\"channelId\":5,\"modelId\":1,\"userId\":0,\"title\":\"小米YU7上市：定位豪华高性能SUV 25.35万元起\",\"style\":\"\",\"image\":\"http:\\/\\/127.0.0.1:8088\\/storage\\/2026\\/09\\/14\\/132258_be4d7ee6.png\",\"images\":\"\",\"keywords\":\"\",\"description\":\"小米YU7上市：定位豪华高性能SUV 25.35万元起\",\"tags\":\"\",\"content\":\"<p><span style=\\\"color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 32px;\\\">6月26日，小米汽车旗下首款SUV——小米YU7上市，定位豪华高性能SUV，推出3个版本，分别为YU7标准版、YU7 Pro版、YU7 Max版，售价25.35万元-32.99万元<\\/span><\\/p>\",\"outlink\":\"\",\"seotitle\":\"\",\"diyname\":\"\",\"orderNum\":0,\"views\":0,\"comments\":0,\"likes\":0,\"publishTime\":\"2026-09-14 13:23:13\",\"flag\":\"\",\"status\":\"0\",\"isguest\":\"1\",\"iscomment\":\"1\",\"createBy\":\"admin\",\"channelIds\":\"\",\"specialIds\":\"\",\"adminId\":1,\"price\":\"0.00\",\"dislikes\":0,\"memo\":\"\",\"createTime\":\"2026-09-14 13:23:13\",\"updateBy\":\"\",\"updateTime\":null,\"delFlag\":\"0\",\"author\":\"\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-22 11:06:27', 42);
INSERT INTO `sys_oper_log` VALUES (393, '修改内容', 0, 'Archives/edit', 'POST', 1, 'admin', '', '/yscms/archives/edit', '127.0.0.1', '', '{\"id\":6,\"channelId\":5,\"modelId\":1,\"userId\":0,\"title\":\"挑选长久安心的出行伙伴 入手豪华燃油车正当时\",\"style\":\"\",\"image\":\"http:\\/\\/127.0.0.1:8088\\/storage\\/2026\\/09\\/14\\/132042_83f6af78.png\",\"images\":\"\",\"keywords\":\"\",\"description\":\"挑选长久安心的出行伙伴 入手豪华燃油车正当时\",\"tags\":\"\",\"content\":\"<p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 2em;\\\">购车，从来都不是简单的选择代步工具，而是挑选长久安心的出行伙伴。梅赛德斯-奔驰将以深厚的车型积淀与市场口碑契合当下消费者对“省心豪华燃油车”的核心诉求。<\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-align: center;\\\"><img src=\\\"https:\\/\\/www.cqn.com.cn\\/auto\\/img\\/2026-08\\/18\\/9169131_b313dab2-9688-437a-8cb0-677d68dbc435.jpg\\\" style=\\\"text-size-adjust: none; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); width: 788.5px; height: auto; margin-bottom: 0.5rem;\\\"><\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 2em;\\\"><strong style=\\\"text-size-adjust: none;\\\">核心技术铸就百年品牌 硬核实力打造难以复刻的稳定可靠<\\/strong><\\/p><p style=\\\"text-size-adjust: none; margin: 20px auto; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, Verdana; font-size: 16px; text-indent: 2em;\\\">汽车的核心价值，终究归于品质与可靠。百年品牌的底气，来自世代传承的造车工艺、持续迭代的核心技术与严苛到极致的品控体系。深耕汽车领域140年的梅赛德斯-奔驰，始终坚守“安全为先、品质为本”的造车理念，依托全球统一的研发、生产、测试标准，打造每一台量产车型。<\\/p>\",\"outlink\":\"\",\"seotitle\":\"\",\"diyname\":\"\",\"orderNum\":0,\"views\":2,\"comments\":0,\"likes\":0,\"publishTime\":\"2026-09-14 13:21:17\",\"flag\":\"\",\"status\":\"0\",\"isguest\":\"1\",\"iscomment\":\"1\",\"createBy\":\"admin\",\"channelIds\":\"\",\"specialIds\":\"\",\"adminId\":1,\"price\":\"0.00\",\"dislikes\":0,\"memo\":\"\",\"createTime\":\"2026-09-14 13:21:17\",\"updateBy\":\"\",\"updateTime\":null,\"delFlag\":\"0\",\"author\":\"\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-22 11:06:41', 34);
