INSERT INTO `sys_oper_log` VALUES (481, '修改单页', 0, 'Page/edit', 'POST', 1, 'admin', '', '/yscms/page/edit', '127.0.0.1', '', '{\"id\":1,\"type\":\"page\",\"title\":\"关于我们\",\"flag\":\"\",\"image\":\"\",\"content\":\"<p><br><\\/p><h3 style=\\\"text-align: start;\\\">意象网络科技——以数字智慧，构建商业新意象<\\/h3><p>意象网络科技是一家专注于企业数字化转型的软件开发与技术服务商。我们致力于通过前沿的互联网技术，为餐饮、零售及各类服务型企业提供高效、稳定、智能的一站式解决方案。 我们的核心产品涵盖：<\\/p><p>**智能点餐系统**：优化点餐流程，提升翻台率与顾客用餐体验，助力餐饮企业实现精细化运营。<\\/p><p>**CRM管理系统**：深度挖掘客户价值，构建精准的用户画像，帮助企业实现从获客到留存的全生命周期管理。<\\/p><p>**定制化电商系统**：打造流畅的在线交易平台，打通线上线下业务壁垒，助力企业拓展数字化销售渠道。秉承“技术赋能商业”的理念，意象网络科技不仅是代码的编写者，更是企业成长的合作伙伴。我们用代码构建商业的“意象”，帮助客户在激烈的市场竞争中确立优势，共创数字未来。<\\/p>\",\"seotitle\":\"\",\"keywords\":\"\",\"description\":\"\",\"diyname\":\"aboutus\",\"showtpl\":\"\",\"views\":9,\"comments\":0,\"orderNum\":0,\"iscomment\":\"1\",\"parsetpl\":\"0\",\"status\":\"0\",\"categoryId\":0,\"adminId\":0,\"icon\":\"\",\"likes\":0,\"dislikes\":0,\"createBy\":\"admin\",\"createTime\":\"2026-09-13 22:39:20\",\"updateBy\":\"admin\",\"updateTime\":\"2026-09-14 19:06:41\",\"delFlag\":\"0\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-23 17:48:21', 26);
INSERT INTO `sys_oper_log` VALUES (482, '修改单页', 0, 'Page/edit', 'POST', 1, 'admin', '', '/yscms/page/edit', '127.0.0.1', '', '{\"id\":1,\"type\":\"page\",\"title\":\"关于我们\",\"flag\":\"\",\"image\":\"\",\"content\":\"<p><br><\\/p><h3 style=\\\"text-align: start;\\\">意象网络科技——以数字智慧，构建商业新意象<\\/h3><p>意象网络科技是一家专注于企业数字化转型的软件开发与技术服务商。我们致力于通过前沿的互联网技术，为餐饮、零售及各类服务型企业提供高效、稳定、智能的一站式解决方案。 我们的核心产品涵盖：<\\/p><p>**智能点餐系统**：优化点餐流程，提升翻台率与顾客用餐体验，助力餐饮企业实现精细化运营。<\\/p><p>**CRM管理系统**：深度挖掘客户价值，构建精准的用户画像，帮助企业实现从获客到留存的全生命周期管理。<\\/p><p>**定制化电商系统**：打造流畅的在线交易平台，打通线上线下业务壁垒，助力企业拓展数字化销售渠道。秉承“技术赋能商业”的理念，意象网络科技不仅是代码的编写者，更是企业成长的合作伙伴。我们用代码构建商业的“意象”，帮助客户在激烈的市场竞争中确立优势，共创数字未来。<\\/p>\",\"seotitle\":\"\",\"keywords\":\"\",\"description\":\"意象网络科技是一家专注于企业数字化转型的软件开发与技术服务商。我们致力于通过前沿的互联网技术，为餐饮、零售及各类服务型企业提供高效、稳定、智能的一站式解决方案。 我们的核心产品涵盖：我们用代码构建商业的“意象”，帮助客户在激烈的市场竞争中确立优势，共创数字未来。\",\"diyname\":\"aboutus\",\"showtpl\":\"\",\"views\":9,\"comments\":0,\"orderNum\":0,\"iscomment\":\"1\",\"parsetpl\":\"0\",\"status\":\"0\",\"categoryId\":0,\"adminId\":0,\"icon\":\"\",\"likes\":0,\"dislikes\":0,\"createBy\":\"admin\",\"createTime\":\"2026-09-13 22:39:20\",\"updateBy\":\"admin\",\"updateTime\":\"2026-09-23 17:48:21\",\"delFlag\":\"0\"}', '{\"code\":200,\"msg\":\"操作成功\"}', 0, '', '2026-09-23 17:49:08', 20);
